--!strict
local Mode=require(script.Parent.ModeService);local Race=require(script.Parent.RaceService);local Profiles=require(script.Parent.PlayerProfileService);local Items=require(script.Parent.ItemService);local Movement=require(script.Parent.MovementModifierService);local remotes=require(script.Parent.RemoteService).Ensure();local Tower={};local sessions:{[Player]:any}={}
local function tower():Instance? local w=workspace:FindFirstChild("PartyObbyWorld");local maps=w and w:FindFirstChild("TowerMaps");return maps and maps:FindFirstChild("Tower01") end
function Tower.Start(p:Player):boolean local map=tower();if not map or not Profiles.IsProfileLoaded(p) then return false end;local start=map:FindFirstChild("TowerStart");if not start or not start:IsA("BasePart") then return false end;local s=Mode.Get(p);if s.IsQueued or s.IsInMatch or s.IsInTower then return false end;Items.ClearPlayer(p);s.CurrentMode="SoloTower";s.IsInLobby=false;s.IsInTower=true;s.CurrentMapId="Tower01";s.CurrentMatchId="Tower-"..p.UserId.."-"..math.floor(os.clock()*1000);local bestMs=(Profiles.GetProfile(p)::any).Tower.BestTowerTimes.Tower01 or 0;local best=bestMs/1000;sessions[p]={floor=0,started=0,lastCFrame=start.CFrame,active=false,runId=s.CurrentMatchId};Race.Teleport(p,start.CFrame,8);Movement.AddModifier(p,"TowerStartLock",0);remotes.ModeStateChanged:FireClient(p,{mode="SoloTower",inTower=true});remotes.TowerProgressUpdated:FireClient(p,{floor=0,total=10,best=best,countdown=3});task.spawn(function()for n=3,1,-1 do remotes.TowerProgressUpdated:FireClient(p,{floor=0,total=10,best=best,countdown=n});task.wait(1) end;local session=sessions[p];if session then session.started=os.clock();session.active=true;Movement.RemoveModifier(p,"TowerStartLock");remotes.TowerProgressUpdated:FireClient(p,{floor=0,total=10,best=best,countdown="GO"});print(string.format("[Tower] %s started Tower01",p.Name)) end end);return true end
function Tower.Leave(p:Player) sessions[p]=nil end
function Tower.Session(p:Player):any return sessions[p] end
return Tower
